import{_ as n,a0 as p,w as i,s as d,ao as r,I as l,x as e,a1 as s,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"Linux有问必答：如何在命令行创建一个MySQL数据库 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何在命令行创建一个MySQL数据库 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何在命令行创建一个MySQL数据库 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何在命令行创建一个MySQL数据库 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140919 Linux FAQs with Answers--How to create a MySQL database from the command line","title":"Linux有问必答：如何在命令行创建一个MySQL数据库","tag":"201410","desc":""},"relativePath":"201410/20140919 Linux FAQs with Answers--How to create a MySQL database from the command line.md","filePath":"[post].md"}'),m={name:"201410/20140919 Linux FAQs with Answers--How to create a MySQL database from the command line.md"};function L(u,t,y,T,S,_){const a=p("Link");return i(),d("div",null,[t[16]||(t[16]=r(`<h1 id="linux有问必答-如何在命令行创建一个mysql数据库" tabindex="-1">Linux有问必答：如何在命令行创建一个MySQL数据库 <a class="header-anchor" href="#linux有问必答-如何在命令行创建一个mysql数据库" aria-label="Permalink to “Linux有问必答：如何在命令行创建一个MySQL数据库”">​</a></h1><blockquote><p><strong>问题</strong>：在一个某处运行的MySQL服务器上，我该怎样通过命令行创建和安装一个MySQL数据库呢？</p></blockquote><p>为了能通过命令行创建一个MySQL数据库，你可以使用mysql命令行客户端。下面是通过mysql命令行客户端创建和安装MySQL的步骤。</p><h3 id="第一步-安装mysql客户端" tabindex="-1">第一步：安装MySQL客户端 <a class="header-anchor" href="#第一步-安装mysql客户端" aria-label="Permalink to “第一步：安装MySQL客户端”">​</a></h3><p>当然你得确保MySQL客户端已经安装完毕。如果没有的话，可以按照下面的方法。</p><p>在Debian，Ubuntu 或者 Linux Mint上：</p><pre><code>$ sudo apt-get install mysql-client
</code></pre><p>在Fedora，CentOS 或者 RHEL上：</p><pre><code>$ sudo apt-get install mysql
</code></pre><h3 id="第二步-登陆到mysql服务器" tabindex="-1">第二步：登陆到MySQL服务器 <a class="header-anchor" href="#第二步-登陆到mysql服务器" aria-label="Permalink to “第二步：登陆到MySQL服务器”">​</a></h3><p>首先，你需要使用root用户登陆进你的MySQL数据库，如下：</p><pre><code>$ mysql -u root -h &lt;mysql-server-ip-address&gt; -p 
</code></pre>`,12)),l("p",null,[t[1]||(t[1]=e("请注意：为了能登进远程的MySQL服务器，你需要",-1)),s(a,{href:"http://xmodulo.com/2012/06/how-to-allow-remote-access-to-mysql.html"},{default:o(()=>[...t[0]||(t[0]=[e("开启服务器上的远程访问",-1)])]),_:1}),t[2]||(t[2]=e("，如果你想调用同一主机上的MySQL服务器，你可以省略 ",-1)),t[3]||(t[3]=l("code",null,"-h <mysql-server-ip-address>",-1)),t[4]||(t[4]=e(" 参数",-1))]),t[17]||(t[17]=r(`<pre><code>$ mysql -u root -p
</code></pre><p>你将需要输入MySQL服务器的密码，如果认证成功，MySQL提示将会出现。</p><p><img src="https://www.flickr.com/photos/xmodulo/15272971112/" alt=""></p><h3 id="第三步-创建一个mysql数据库" tabindex="-1">第三步：创建一个MySQL数据库 <a class="header-anchor" href="#第三步-创建一个mysql数据库" aria-label="Permalink to “第三步：创建一个MySQL数据库”">​</a></h3><p>在MySQL提示中输入命令之前，请记住所有的命令都是以分号结束的(否则将不会执行)。另外，考虑输入命令的时候使用大些字母，输入数据库对象使用小写字母。但那不是必须的，只是方便你的阅读。</p><p>现在，让我们创建一个叫做xmodulo_DB的数据库：</p><pre><code>mysql&gt; CREATE DATABASE IF NOT EXISTS xmodulo_DB; 
</code></pre><p><img src="https://farm4.staticflickr.com/3864/15086792487_8e2eaedbcd.jpg" alt=""></p><h3 id="第四步-创建一个数据库表" tabindex="-1">第四步：创建一个数据库表 <a class="header-anchor" href="#第四步-创建一个数据库表" aria-label="Permalink to “第四步：创建一个数据库表”">​</a></h3><p>为了达到演示的目的，我们将会创建一个叫做posts_tbl的表，表里会存储关于文章的如下信息：</p><ul><li>文章的标题</li><li>作者的名字</li><li>作者的姓</li><li>文章可用或者不可用</li><li>文章创建的日期</li></ul><p>这个过程分两步执行：</p><p>首先，选择我们需要使用的数据库：</p><pre><code>mysql&gt; USE xmodulo_DB; 
</code></pre><p>然后，在数据库中创建新表：</p><pre><code>mysql&gt; CREATE TABLE &#39;posts_tbl&#39; (
&#39;post_id&#39; INT UNSIGNED NOT NULL AUTO_INCREMENT, 
&#39;content&#39; TEXT,
&#39;author_FirstName&#39; VARCHAR(100) NOT NULL,
&#39;author_LastName&#39; VARCHAR(50) DEFAULT NULL ,
&#39;isEnabled&#39; TINYINT(1) NOT NULL DEFAULT 1, 
&#39;date&#39; TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ,
PRIMARY KEY ( &#39;post_id&#39; ) 
) TYPE = MYISAM;
</code></pre><p><img src="https://farm4.staticflickr.com/3870/15086654980_39d2d54d72.jpg" alt=""></p><h3 id="第五步-创建一个用户-并授予权限" tabindex="-1">第五步：创建一个用户，并授予权限 <a class="header-anchor" href="#第五步-创建一个用户-并授予权限" aria-label="Permalink to “第五步：创建一个用户，并授予权限”">​</a></h3><p>当涉及到访问我们新创的数据库和表的时候，创建一个新用户是一个很好的主意。这样做就可以让用户在没有整个MySQL服务器权限的情况下，去访问那个数据库(而且只能是那个数据库)</p><p>你可以创建新用户，授予权限，并且使改变生效：</p><pre><code>mysql&gt; GRANT ALL PRIVILEGES ON xmodulo_DB.* TO &#39;new_user&#39;@&#39;%&#39; IDENTIFIED BY &#39;new_password&#39;;
mysql&gt; FLUSH PRIVILEGES;
</code></pre><p>&#39;new_user&#39;和&#39;new_password&#39;分别指的是新的用户名和他的密码。这条信息将会被保存在mysql.user表中，而且密码会被加密。</p><h3 id="第六步-测试" tabindex="-1">第六步：测试 <a class="header-anchor" href="#第六步-测试" aria-label="Permalink to “第六步：测试”">​</a></h3><p>让我们插入一个虚拟的记录到posts_tbl表：</p><pre><code>mysql&gt; USE xmodulo_DB;
mysql&gt; INSERT INTO posts_tbl (content, author_FirstName, author_Las tName)
VALUES (&#39;Hi! This is some dummy text.&#39;, &#39;Gabriel&#39;, &#39;Canepa&#39;);
</code></pre><p>然后查看posts_tbl表中的所有记录：</p><pre><code>mysql&gt; SELECT * FROM posts_tbl;
</code></pre><p><img src="https://farm4.staticflickr.com/3896/15086792527_39a987d8bd_z.jpg" alt=""></p><p>注意：MySQL会在我们先前定义的地方自动插入适当的默认值(比如，&#39;isEnabled&#39;和&#39;date&#39;)。</p><hr>`,30)),l("p",null,[t[6]||(t[6]=e("via: ",-1)),s(a,{href:"http://ask.xmodulo.com/create-mysql-database-command-line.html"},{default:o(()=>[...t[5]||(t[5]=[e("http://ask.xmodulo.com/create-mysql-database-command-line.html",-1)])]),_:1})]),l("p",null,[t[9]||(t[9]=e("译者：",-1)),s(a,{href:"https://github.com/su-kaiyao"},{default:o(()=>[...t[7]||(t[7]=[e("su-kaiyao",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),s(a,{href:"https://github.com/wxy"},{default:o(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=e("本文由 ",-1)),s(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创翻译，",-1)),s(a,{href:"http://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[e("Linu x中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const f=n(m,[["render",L]]);export{M as __pageData,f as default};
